<?php
namespace Tests\Feature;
use App\Models\User;
use App\Services\{InvoiceCalculator,IntegrationContract,StatutorySales,MerchantWallet,EisDocumentReadiness};
use Illuminate\Support\Facades\{DB,Crypt};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Tests\TestCase;
class StatutorySalesTest extends TestCase {
 private User $owner; private User $admin; private string $merchant;
 protected function setUp():void {parent::setUp();config(['database.default'=>'sqlite','database.connections.sqlite.database'=>':memory:','cache.default'=>'array','notifications.dispatch_enabled'=>false]);DB::purge('sqlite');$this->artisan('migrate:fresh',['--force'=>true])->assertSuccessful();$this->owner=$this->user('merchant');$this->admin=$this->user('super_admin');$this->merchant=(string)Str::uuid();DB::table('merchants')->insert(['id'=>$this->merchant,'merchant_account_id'=>$this->owner->id,'business_name'=>'Synthetic Benefits QA','tin'=>'123456789000','address'=>'Synthetic Address','status'=>'active','vat_registered'=>true]);DB::transaction(fn()=>app(MerchantWallet::class)->credit($this->merchant,30000,(string)Str::uuid(),'Synthetic test funds',(string)$this->admin->id));}
 private function user(string $role):User {$u=User::factory()->create(['api_token'=>Str::random(64),'api_mfa_verified_at'=>now(),'mfa_secret'=>Crypt::encryptString('SYNTHETICKEY')]);DB::table('profiles')->insert(['id'=>$u->id,'email'=>$u->email,'role'=>$role]);return $u;}
 private function benefit(string $c='pwd'):array {return ['category'=>$c,'scope'=>$c==='solo_parent'?'diapers':'restaurant','beneficiary_name'=>'Synthetic Eligible Buyer','id_number'=>'SYNTHETIC-ID-001','evidence_reference'=>'Synthetic identity and eligibility evidence','eligibility_confirmed'=>true,...($c==='solo_parent'?['child_birth_date'=>now()->subYears(2)->toDateString(),'id_valid_until'=>now()->addMonth()->toDateString(),'booklet_reference'=>'Synthetic booklet','income_below_250000'=>true]:[])];}
 private function key(string $env='live'):string {$k=Str::random(64);DB::table('merchant_api_keys')->insert(['id'=>(string)Str::uuid(),'merchant_id'=>$this->merchant,'name'=>'Synthetic benefit test','environment'=>$env,'branch_code'=>'00000','branch_type'=>'main','key_hash'=>hash('sha256',$k),'key_prefix'=>'test','key_last_four'=>'test','status'=>'active','scopes'=>'["transactions:write","transactions:read"]','ip_whitelist'=>'[]','rate_limit_per_day'=>50000,'expires_at'=>now()->addDay()]);return $k;}
 private function payload(string $category='pwd',string $ref='A'):array {$profile=DB::table('integration_source_profiles')->value('id');if(!$profile){$profile=(string)Str::uuid();DB::table('integration_source_profiles')->insert(['id'=>$profile,'merchant_id'=>$this->merchant,'branch_code'=>'00000','source_system'=>'synthetic-benefits','vat_registered'=>true,'seller_name'=>'Synthetic Benefits QA','seller_tin'=>'123456789000','seller_address'=>'Synthetic address','authority_reference'=>'Synthetic reviewed source','evidence_reference'=>'Synthetic evidence','valid_from'=>now()->subYear(),'valid_until'=>now()->addYear(),'status'=>'active','reviewed_by'=>(string)$this->admin->id,'reviewed_at'=>now(),'request_id'=>(string)Str::uuid(),'request_hash'=>str_repeat('a',64)]);}
 return ['schema_version'=>'NUERS-ingestion-1','record_mode'=>'source_capture','source_profile_id'=>$profile,'source_system'=>'synthetic-benefits','source_event_id'=>$ref,'external_reference'=>$ref,'event_type'=>'invoice.finalized','occurred_at'=>now()->subMinute()->toIso8601String(),'branch_code'=>'00000','receipt_number'=>'SYNTHETIC-'.$ref,'document_type'=>'sales_invoice','payment_method'=>'cash','tax_type'=>'vatable','vat_inclusive'=>true,'gross_amount'=>$category==='national_athlete_coach'?896:($category==='solo_parent'?900:800),'sales_benefit'=>$this->benefit($category),'items'=>[['description'=>'Synthetic qualifying item','quantity'=>1,'unit_price'=>1120,'tax_type'=>'vatable','benefit_eligible'=>true]]];}
 public function test_four_categories_compute_distinct_tax_and_discount_rules():void {foreach(['pwd'=>[80000,20000,0,12000],'senior_citizen'=>[80000,20000,0,12000],'national_athlete_coach'=>[89600,20000,9600,2400],'solo_parent'=>[90000,10000,0,12000]] as $c=>[$total,$discount,$vat,$adjustment]){$r=app(InvoiceCalculator::class)->calculate([['description'=>'Eligible','quantity'=>1,'unit_price'=>112000,'tax_type'=>'vatable','benefit_eligible'=>true]],true,0,0,true,$this->benefit($c));$this->assertSame($total,$r['total_amount']);$this->assertSame($discount,$r['statutory_discount_amount']);$this->assertSame($vat,$r['vat_amount']);$this->assertSame($adjustment,$r['vat_relief_amount']);}}
 public function test_non_vat_seller_never_removes_fictitious_vat_and_mixed_baskets_discount_only_eligible_lines():void {$calc=app(InvoiceCalculator::class);$r=$calc->calculate([['quantity'=>1,'unit_price'=>112000,'tax_type'=>'non_vat','benefit_eligible'=>true]],false,0,0,true,$this->benefit());$this->assertSame(89600,$r['total_amount']);$this->assertSame(22400,$r['statutory_discount_amount']);$this->assertSame(0,$r['vat_relief_amount']);$r=$calc->calculate([['quantity'=>1,'unit_price'=>112000,'tax_type'=>'vatable','benefit_eligible'=>true],['quantity'=>1,'unit_price'=>112000,'tax_type'=>'vatable']],true,0,0,true,$this->benefit());$this->assertSame(192000,$r['total_amount']);$this->assertSame(12000,$r['vat_amount']);$this->assertSame(80000,$r['vat_exempt_amount']);$this->assertSame(100000,$r['taxable_amount']);}
 public function test_exclusive_prices_and_rounding_reconcile():void {$r=app(InvoiceCalculator::class)->calculate([['quantity'=>3,'unit_price'=>3333,'tax_type'=>'vatable','benefit_eligible'=>true]],true,0,0,false,$this->benefit('national_athlete_coach'));$this->assertSame(2000,$r['discount_amount']);$this->assertSame(7999,$r['taxable_amount']);$this->assertSame(960,$r['vat_amount']);$this->assertSame(8959,$r['total_amount']);$this->assertSame(0,$r['vat_relief_amount']);}
 public function test_api_persists_classification_reconciles_and_replays_without_recharging():void {$p=$this->payload();$this->withHeader('X-NUERS-API-Key',$this->key());$r=$this->postJson('/api/integrations/transactions',$p)->assertCreated()->assertJsonPath('calculation.sale_category','pwd')->assertJsonPath('calculation.gross_amount',800)->assertJsonPath('calculation.statutory_discount_amount',200)->assertJsonPath('calculation.vat_amount',0);$id=$r->json('receipt_id');$this->assertDatabaseHas('transaction_receipts',['id'=>$id,'sale_category'=>'pwd','statutory_discount_amount'=>200,'vat_relief_amount'=>120]);$this->assertTrue(app(EisDocumentReadiness::class)->inspect('receipt',$id)['financial_validation_passed']);$entries=DB::table('merchant_wallet_entries')->count();$this->postJson('/api/integrations/transactions',$p)->assertOk()->assertJsonPath('duplicate',true);$this->assertDatabaseCount('merchant_wallet_entries',$entries);$p['sales_benefit']['id_number']='SYNTHETIC-CHANGED';$this->postJson('/api/integrations/transactions',$p)->assertConflict();}
 public function test_missing_evidence_unsupported_scope_false_eligibility_and_stacked_discounts_are_rejected():void {$p=$this->payload();$this->withHeader('X-NUERS-API-Key',$this->key('sandbox'));foreach([['id_number'=>''],['scope'=>'ordinary_retail'],['eligibility_confirmed'=>false],['unexpected'=>'injected']] as $change){$v=$p;$v['sales_benefit']=array_replace($v['sales_benefit'],$change);$this->postJson('/api/integrations/transactions',$v)->assertUnprocessable();}$v=$p;$v['items'][0]['discount_pct']=10;$this->postJson('/api/integrations/transactions',$v)->assertUnprocessable();$v=$p;$v['items'][0]['benefit_eligible']=false;$this->postJson('/api/integrations/transactions',$v)->assertUnprocessable();$v=$p;unset($v['sales_benefit']);$this->postJson('/api/integrations/transactions',$v)->assertUnprocessable();$this->assertDatabaseCount('integration_sandbox_events',0);}
 public function test_solo_parent_requires_valid_spic_booklet_income_and_child_age_at_sale():void {$p=$this->payload('solo_parent');$this->withHeader('X-NUERS-API-Key',$this->key('sandbox'));foreach([['income_below_250000'=>false],['child_birth_date'=>now()->subYears(7)->toDateString()],['child_birth_date'=>now()->addDay()->toDateString()],['id_valid_until'=>now()->subDay()->toDateString()],['booklet_reference'=>'']] as $change){$v=$p;$v['sales_benefit']=array_replace($v['sales_benefit'],$change);$this->postJson('/api/integrations/transactions',$v)->assertUnprocessable();}$this->postJson('/api/integrations/transactions',$p)->assertCreated()->assertJsonPath('calculation.gross_amount',900);$this->assertDatabaseCount('transaction_receipts',0);}
 public function test_merchant_draft_uses_same_calculator_and_saved_document_shows_beneficiary():void {$p=['invoice_number'=>'SYNTHETIC-DRAFT','request_id'=>(string)Str::uuid(),'document_type'=>'sales_invoice','status'=>'draft','buyer_name'=>'Synthetic Eligible Buyer','issue_date'=>now()->toDateString(),'sales_benefit'=>$this->benefit(),'line_items'=>[['line_number'=>1,'description'=>'Synthetic eligible item','quantity'=>1,'unit_price'=>112000,'tax_type'=>'vatable','benefit_eligible'=>true,'discount_amount'=>20000,'vat_amount'=>0,'taxable_amount'=>0,'line_total'=>80000]]];$this->withToken($this->owner->api_token)->postJson('/api/business-invoices',$p)->assertCreated();$row=DB::table('business_invoices')->first();$this->assertSame('pwd',$row->sale_category);$this->assertEquals(800,$row->total_amount);$this->assertNotEmpty(DB::table('business_invoice_items')->value('benefit_details'));$this->getJson('/api/invoice-center/invoice/'.$row->id)->assertOk()->assertJsonPath('document.sales_benefit.id_number','SYNTHETIC-ID-001')->assertJsonPath('document.statutory_discount',200);DB::table('business_invoices')->where('id',$row->id)->update(['status'=>'issued']);$this->assertTrue(app(EisDocumentReadiness::class)->inspect('invoice',$row->id)['financial_validation_passed']);}
 public function test_merchant_admin_filters_and_all_export_formats_match_without_exposing_id_numbers():void {$p=$this->payload('pwd','PWD');$this->withHeader('X-NUERS-API-Key',$this->key());$this->postJson('/api/integrations/transactions',$p)->assertCreated();$this->postJson('/api/integrations/transactions',$this->payload('national_athlete_coach','NAAC'))->assertCreated();$this->flushHeaders();$from=now()->subDay()->toDateString();$to=now()->addDay()->toDateString();$q='from='.$from.'&to='.$to.'&sale_category=pwd';$this->withToken($this->owner->api_token)->getJson('/api/merchant/sales-reports?'.$q)->assertOk()->assertJsonPath('count',1)->assertJsonPath('totals.statutory_discount',20000)->assertJsonPath('data.0.sale_category','pwd');$csv=$this->get('/api/merchant/sales-reports/export?format=csv&'.$q)->assertOk()->getContent();$this->assertStringContainsString('SYNTHETIC-PWD',$csv);$this->assertStringNotContainsString('SYNTHETIC-NAAC',$csv);$this->assertStringNotContainsString('SYNTHETIC-ID-001',$csv);$xlsx=$this->get('/api/merchant/sales-reports/export?format=xlsx&'.$q)->assertOk()->getContent();$this->assertStringStartsWith('PK',$xlsx);$this->withToken($this->admin->api_token)->getJson('/api/transaction-workspace?'.$q)->assertOk()->assertJsonPath('total',1)->assertJsonPath('data.0.sale_category','pwd');$this->getJson('/api/invoice-center?'.$q)->assertOk()->assertJsonPath('total',1);foreach(['/api/transaction-workspace/export?','/api/invoice-center/export?'] as $url){$csv=$this->get($url.$q)->assertOk()->streamedContent();$this->assertStringContainsString('SYNTHETIC-PWD',$csv);$this->assertStringNotContainsString('SYNTHETIC-NAAC',$csv);$this->assertStringNotContainsString('SYNTHETIC-ID-001',$csv);}}
 public function test_sandbox_filter_is_isolated_and_beneficiary_is_not_in_list_metadata():void {$this->withHeader('X-NUERS-API-Key',$this->key('sandbox'))->postJson('/api/integrations/transactions',$this->payload())->assertCreated();$this->flushHeaders();$r=$this->withToken($this->owner->api_token)->getJson('/api/merchant/sandbox-records?sale_category=pwd')->assertOk()->assertJsonPath('total',1);$this->assertStringNotContainsString('SYNTHETIC-ID-001',$r->getContent());$this->getJson('/api/merchant/sandbox-records?sale_category=solo_parent')->assertOk()->assertJsonPath('total',0);$this->assertDatabaseCount('transaction_receipts',0);}

 public function test_admin_draft_and_merchant_document_exports_preserve_benefits():void {
  $p=['request_id'=>(string)Str::uuid(),'merchant_id'=>$this->merchant,'document_type'=>'sales_invoice','buyer_name'=>'Synthetic Buyer','issue_date'=>now()->toDateString(),'vat_inclusive'=>true,'tax_type'=>'vatable','sales_benefit'=>$this->benefit('national_athlete_coach'),'items'=>[['description'=>'Synthetic qualifying meal','quantity'=>1,'unit_price'=>1120,'benefit_eligible'=>true]]];
  $this->withToken($this->admin->api_token)->postJson('/api/invoice-center',$p)->assertCreated();
  $this->postJson('/api/invoice-center',$p)->assertOk()->assertJsonPath('duplicate',true);
  $this->assertDatabaseHas('business_invoices',['id'=>$p['request_id'],'sale_category'=>'national_athlete_coach','total_amount'=>896,'vat_amount'=>96]);
  $this->withToken($this->owner->api_token)->getJson('/api/merchant/records?mode=documents&sale_category=national_athlete_coach')->assertOk()->assertJsonPath('pagination.total',1)->assertJsonPath('data.0.sale_category','national_athlete_coach');
  $this->getJson('/api/merchant/records?mode=documents&sale_category=pwd')->assertOk()->assertJsonPath('pagination.total',0);
  $csv=$this->get('/api/merchant/records/export?mode=documents&sale_category=national_athlete_coach')->assertOk()->streamedContent();
  $this->assertStringContainsString('national_athlete_coach',$csv);$this->assertStringNotContainsString('SYNTHETIC-ID-001',$csv);
  DB::table('business_invoices')->where('id',$p['request_id'])->update(['status'=>'issued']);
  $this->assertTrue(app(EisDocumentReadiness::class)->inspect('invoice',$p['request_id'])['financial_validation_passed']);
 }
 public function test_public_preview_accepts_synthetic_benefits_and_rejects_real_ids():void {
  $p=$this->payload();$p['external_reference']='SAMPLE-ELIGIBLE';
  $body=['is_test'=>true,'action'=>'ingestion','seller_vat_registered'=>true,'payload'=>$p];
  $this->postJson('/api/developer/sandbox',$body)->assertOk()->assertJsonPath('calculation.gross_amount',800);
  $body['payload']['sales_benefit']['id_number']='12345';$this->postJson('/api/developer/sandbox',$body)->assertUnprocessable();
  $this->assertDatabaseCount('transaction_receipts',0);$this->assertDatabaseCount('integration_sandbox_events',0);
 }
 public function test_batch_mixed_categories_and_payment_receipts_remain_distinct():void {
  $this->withHeader('X-NUERS-API-Key',$this->key());$events=[$this->payload('pwd','BATCH1'),$this->payload('solo_parent','BATCH2')];
  $this->postJson('/api/integrations/transactions/batch',['events'=>$events])->assertSuccessful();
  $p=$this->payload('pwd','PAYMENT');$p['document_type']='payment_receipt';$p['event_type']='payment.recorded';
  $before=DB::table('merchant_wallet_entries')->count();$this->postJson('/api/integrations/transactions',$p)->assertCreated();$this->assertDatabaseCount('merchant_wallet_entries',$before);
  $this->flushHeaders();$this->withToken($this->owner->api_token)->getJson('/api/merchant/records?mode=transactions&sale_category=pwd')->assertOk()->assertJsonPath('pagination.total',2);
  $this->getJson('/api/merchant/sales-reports?sale_category=pwd&from='.now()->subDay()->toDateString().'&to='.now()->addDay()->toDateString())->assertOk()->assertJsonPath('totals.statutory_discount',20000);
 }

 public function test_benefit_invoice_and_filtered_report_render_real_pdfs_without_mutating_originals():void {
  $this->withHeader('X-NUERS-API-Key',$this->key())->postJson('/api/integrations/transactions',$this->payload())->assertCreated();$id=DB::table('transaction_receipts')->value('id');$before=(array)DB::table('transaction_receipts')->where('id',$id)->first();$this->flushHeaders();
  $invoice=$this->withToken($this->owner->api_token)->get('/api/document-copies/receipt/'.$id.'/pdf')->assertOk()->assertHeader('Content-Type','application/pdf')->getContent();
  $report=$this->get('/api/merchant/sales-reports/export?format=pdf&sale_category=pwd&from='.now()->subDay()->toDateString().'&to='.now()->addDay()->toDateString())->assertOk()->assertHeader('Content-Type','application/pdf')->getContent();
  $this->assertStringStartsWith('%PDF-',$invoice);$this->assertStringStartsWith('%PDF-',$report);$this->assertSame($before,(array)DB::table('transaction_receipts')->where('id',$id)->first());
  if(getenv('NUERS_QA_ARTIFACTS')==='1'){file_put_contents(base_path('.local/statutory-sales-20261018/invoice-qa.pdf'),$invoice);file_put_contents(base_path('.local/statutory-sales-20261018/report-qa.pdf'),$report);}
 }
}
